"""Request and response of the chat endpoints: the HTTP side of the contract with the frontend."""

from pydantic import BaseModel, Field


class ChatRequest(BaseModel):
    question: str = Field(min_length=1, max_length=10_000, description="Checked again by the sanitizer.")
    conversation_id: str | None = Field(
        default=None,
        max_length=100,
        pattern=r"^[A-Za-z0-9_\-]+$",
        description=(
            "The thread, chosen by the client (one uuid per conversation). Generated by the server when "
            "absent. It is NOT the whole key: the backend prepends tenant and user from the token, so "
            "sending someone else's id does not open their thread."
        ),
    )
    language: str | None = Field(
        default=None, min_length=2, max_length=5, description="ISO 639-1. Falls back to the user's language."
    )


class ChatResponse(BaseModel):
    answer: str
    conversation_id: str = Field(description="Send it back in the next turn of the same conversation.")
    message_id: str | None = Field(default=None, description="Persisted answer; what a vote points at.")
